mapper.select:
SELECT STATUS
FROM jobseeker_applicant
WHERE JOBSEEKER_IDX = #{jobSeekerIdx}
AND JOB_POSTS_IDX = #{jobPostsIdx}
LIMIT 1

mapper.delete:
DELETE FROM jobseeker_applicant
WHERE JOBSEEKER_IDX = #{jobSeekerIdx}
AND JOB_POSTS_IDX = #{jobPostsIdx}
AND STATUS = 'SCRAP'

mapper.update:
UPDATE jobseeker_applicant
SET STATUS = #{status}
WHERE JOBSEEKER_IDX = #{jobSeekerIdx}
AND JOB_POSTS_IDX = #{jobPostsIdx}

UPDATE jobseeker_applicant
SET APPLIED_AT = NOW()
WHERE JOBSEEKER_IDX = #{jobSeekerIdx}
AND JOB_POSTS_IDX = #{jobPostsIdx}
